/* @lc app=leetcode id=3485 lang=kotlin */ class Solution { fun longestCommonPrefix(words: Array<String>, k: Int): IntArray = words.size.let { n -> IntArray(words.sumOf { it.length } + 2).let { nc -> IntArray(words.sumOf { it.length } + 2).let { dep -> IntArray(1) { 1 }.let { nxt -> HashMap<Long, Int>().let { ch -> words.map { w -> ArrayList<Int>().also { p -> w.fold(0) { node, c -> ch.getOrPut(node * 26L + (c - 'a')) { nxt[0]++ }.also { nc[it]++ }.also { p.add(it) }.also { dep[it] = p.size } } } }.let { paths -> (1 until nxt[0]).filter { nc[it] >= k + 1 }.maxOfOrNull { dep[it] }.let { it ?: 0 }.let { dd -> (1 until nxt[0]).filter { nc[it] == k }.sortedByDescending { dep[it] }.let { lst -> IntArray(n) { i -> if (n - 1 < k) 0 else maxOf(dd, paths[i].toHashSet().let { ps -> lst.firstOrNull { it !in ps }?.let { dep[it] } ?: 0 }) } } } } } } } } } }